={
    "prospect":{
        "requestdate":"{{ $now.format('yyyy-MM-dd') }}",
        "customer":
            {
                "interest":"{{ $('When Executed by Another Workflow').first().json.tipoInteres }}",
                "contacts":[
                    {
                        "names":
                            [
                                {
                                    "part":"first",
                                    "value":"{{ $('When Executed by Another Workflow').first().json.name|| 'Sin especificar'}}"
                                },
                                {
                                    "part":"last",
                                    "value":"APELLIDO"
                                }
                            ],
                        "phones":
                            [
                                {
                                    "type": "mobile",
                                   "field":"MobilePhone",
                                    "value":"{{$('When Executed by Another Workflow').first().json.from}}"
                                }
                            ]
                    }
                ],
                "comments":"{{ $('When Executed by Another Workflow').first().json.preguntas || '' }}"
            },
        "vehicles":
            [
                {
                    "make":"Toyota",
                    "model":"{{ $('When Executed by Another Workflow').first().json.modelo }}",
                    "modelo_code":"{{ $('When Executed by Another Workflow').first().json.codigoModelo || '' }}"
                }
            ],
        "provider":
            {
                "name":
                    {
                        "value":"Whatsapp bot",
                        "origin":"Whatsapp bot"
                    }
            },
        "email":"{{ $('When Executed by Another Workflow').first().json.email}}",

        "boca de venta": "{{ $('When Executed by Another Workflow').first().json['Boca de venta'] || 'PILA' }}"
    }
}

